import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Button,
  Checkbox,
  FormActions,
  Input,
  LeaveConfirmModal,
  LinPageLayout,
  Modal,
  NumberInput,
  SearchTextInput,
  Select,
  TextArea,
  dispatchAppToast,
  useCatalogTableBusy,
  useDirtyTracking,
  useLeaveConfirm,
} from '@linm-soft-org/linm-web-common-components';
import { Tag, Popconfirm } from '@/components/common';
import { fpcService } from '../../../services/fpc/service';
import type {
  ExpansionFormulaDto,
  CreateExpansionFormulaDto,
  UpdateExpansionFormulaDto,
  ExpansionFormulaKind,
} from '../../../services/fpc/types';
import { resolveApiErrorMessage } from '../../../services/catalogUiSchemaService';
import { useAppDispatch } from '../../../store/hooks';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import { matchesCodeOrName, normalizeCode } from '../../../utils/codeField';
import styles from './ExpansionFormulaPage.module.css';

const TEST_ID = 'cong-thuc-mo-rong';
const PAGE_SIZE = 50;

type FormMode = 'create' | 'edit' | 'view';
type FormErrors = Partial<Record<'code' | 'name' | 'formulaKind', string>>;

type FormState = {
  code: string;
  name: string;
  formulaKind: ExpansionFormulaKind;
  engineKey: string;
  description: string;
  thresholdFast: number | null;
  thresholdOk: number | null;
  sortOrder: number;
  isActive: boolean;
  isDefault: boolean;
};

const KIND_OPTIONS = [
  { value: 'BreakEven', label: 'Hòa vốn' },
  { value: 'Payback', label: 'Hoàn vốn' },
  { value: 'Recommendation', label: 'Khuyến nghị' },
];

const KIND_LABEL: Record<string, string> = {
  BreakEven: 'Hòa vốn',
  Payback: 'Hoàn vốn',
  Recommendation: 'Khuyến nghị',
};

const EMPTY_FORM: FormState = {
  code: '',
  name: '',
  formulaKind: 'BreakEven',
  engineKey: '',
  description: '',
  thresholdFast: null,
  thresholdOk: null,
  sortOrder: 50,
  isActive: true,
  isDefault: false,
};

function dtoToForm(item: ExpansionFormulaDto): FormState {
  return {
    code: item.code,
    name: item.name,
    formulaKind: (item.formulaKind as ExpansionFormulaKind) || 'BreakEven',
    engineKey: item.engineKey || '',
    description: item.description || '',
    thresholdFast: item.thresholdFast ?? null,
    thresholdOk: item.thresholdOk ?? null,
    sortOrder: item.sortOrder ?? 0,
    isActive: item.isActive,
    isDefault: item.isDefault,
  };
}

export default function ExpansionFormulaPage() {
  const dispatch = useAppDispatch();
  const {
    canViewExpansionFormula,
    canManageExpansionFormula,
    canDeleteExpansionFormula,
  } = useFpcPermissions();
  const { onDirtyChange, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [data, setData] = useState<ExpansionFormulaDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [kindFilter, setKindFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [modalOpen, setModalOpen] = useState(false);
  const [formMode, setFormMode] = useState<FormMode>('create');
  const [editingItem, setEditingItem] = useState<ExpansionFormulaDto | null>(null);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const list = await fpcService.getExpansionFormulaList(kindFilter || undefined);
      setData(list ?? []);
    } catch {
      setData([]);
      dispatchAppToast(dispatch, { message: 'Không tải được danh mục công thức', type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [dispatch, kindFilter]);

  useEffect(() => {
    const t = window.setTimeout(() => { void fetchData(); }, 0);
    return () => window.clearTimeout(t);
  }, [fetchData]);

  const filtered = useMemo(() => {
    const q = search.trim();
    if (!q) return data;
    return data.filter(r => matchesCodeOrName(q, r.code, r.name));
  }, [data, search]);

  const totalCount = filtered.length;
  const pageItems = useMemo(
    () => filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE),
    [filtered, page],
  );
  const selectedItem = data.find(d => d.id === selectedId) ?? null;
  const { showTableLoading } = useCatalogTableBusy(loading);
  const viewOnly = formMode === 'view';

  const handleSearch = () => {
    setSearch(searchDraft.trim());
    setPage(1);
  };

  const openCreate = () => {
    setFormMode('create');
    setEditingItem(null);
    setForm(EMPTY_FORM);
    setErrors({});
    markClean();
    setModalOpen(true);
  };

  const openEdit = (item: ExpansionFormulaDto) => {
    setFormMode('edit');
    setEditingItem(item);
    setForm(dtoToForm(item));
    setErrors({});
    markClean();
    setModalOpen(true);
  };

  const openView = (item: ExpansionFormulaDto) => {
    setFormMode('view');
    setEditingItem(item);
    setForm(dtoToForm(item));
    setErrors({});
    markClean();
    setModalOpen(true);
  };

  const closeModal = () => {
    setModalOpen(false);
    markClean();
  };

  const clearFieldError = (key: keyof FormErrors) => {
    setErrors(prev => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });
  };

  const validate = (): boolean => {
    const next: FormErrors = {};
    if (!form.code.trim()) next.code = 'Nhập mã';
    if (!form.name.trim()) next.name = 'Nhập tên';
    if (!form.formulaKind) next.formulaKind = 'Chọn loại';
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSave = async () => {
    if (viewOnly || !validate()) return;
    setSubmitting(true);
    try {
      if (formMode === 'create') {
        const dto: CreateExpansionFormulaDto = {
          code: normalizeCode(form.code),
          name: form.name.trim(),
          formulaKind: form.formulaKind,
          engineKey: form.engineKey.trim() || normalizeCode(form.code),
          description: form.description.trim() || null,
          thresholdFast: form.formulaKind === 'Recommendation' ? form.thresholdFast : null,
          thresholdOk: form.formulaKind === 'Recommendation' ? form.thresholdOk : null,
          sortOrder: form.sortOrder,
          isActive: form.isActive,
          isDefault: form.isDefault,
        };
        await fpcService.createExpansionFormula(dto);
        dispatchAppToast(dispatch, { message: 'Đã tạo công thức', type: 'success' });
      } else if (editingItem) {
        const dto: UpdateExpansionFormulaDto = {
          name: form.name.trim(),
          formulaKind: form.formulaKind,
          engineKey: form.engineKey.trim() || editingItem.engineKey,
          description: form.description.trim() || null,
          thresholdFast: form.formulaKind === 'Recommendation' ? form.thresholdFast : null,
          thresholdOk: form.formulaKind === 'Recommendation' ? form.thresholdOk : null,
          sortOrder: form.sortOrder,
          isActive: form.isActive,
          isDefault: form.isDefault,
        };
        await fpcService.updateExpansionFormula(editingItem.id, dto);
        dispatchAppToast(dispatch, { message: 'Đã lưu công thức', type: 'success' });
      }
      closeModal();
      void fetchData();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Lưu thất bại'),
        type: 'error',
      });
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await fpcService.deleteExpansionFormula(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa công thức', type: 'success' });
      if (selectedId === id) setSelectedId(null);
      void fetchData();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Xóa thất bại'),
        type: 'error',
      });
    }
  };

  const patchForm = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    if (viewOnly) return;
    markDirty();
    if (key === 'code' || key === 'name' || key === 'formulaKind') clearFieldError(key as keyof FormErrors);
    setForm(f => ({ ...f, [key]: value }));
  };

  if (!canViewExpansionFormula) {
    return (
      <div className={styles.catalogListRoot} data-testid={`${TEST_ID}-list`}>
        <p>Bạn không có quyền xem danh mục công thức.</p>
      </div>
    );
  }

  const modalTitle =
    formMode === 'view' ? 'Xem công thức'
      : formMode === 'edit' ? 'Sửa công thức'
        : 'Tạo công thức';

  return (
    <div className={styles.catalogListRoot} data-catalog-list-page data-testid={`${TEST_ID}-list`}>
      <LinPageLayout
        kind="catalog"
        testIdPrefix={TEST_ID}
        pageClassName={styles.catalogListPage}
        header={{
          title: 'Danh mục công thức mô phỏng mở rộng',
          hint: 'Hòa vốn · Hoàn vốn · Khuyến nghị — dùng khi Chạy mô phỏng',
          titleIconClass: 'fas fa-calculator',
        }}
        listTitle="Danh sách công thức"
        listRowMenuHelp
        filterMaxWidthPx={1000}
        showTableLoading={showTableLoading}
        catalogToolbar={{
          testIdPrefix: TEST_ID,
          canAdd: canManageExpansionFormula,
          showView: !!selectedItem,
          showEdit: !!selectedItem && canManageExpansionFormula,
          canDelete: !!selectedItem && canDeleteExpansionFormula,
          canHistory: false,
          selectedCount: selectedItem ? 1 : 0,
          onAdd: openCreate,
          onView: () => selectedItem && openView(selectedItem),
          onEdit: () => selectedItem && openEdit(selectedItem),
          onRefresh: fetchData,
          onDelete: () => {
            if (selectedItem) void handleDelete(selectedItem.id);
          },
        }}
        filters={(
          <>
            <label className={styles.filterLabel}>
              Loại
              <Select
                value={kindFilter}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                  setKindFilter(e.target.value);
                  setPage(1);
                }}
                options={[{ value: '', label: 'Tất cả' }, ...KIND_OPTIONS]}
                data-testid={`${TEST_ID}-kind-filter`}
              />
            </label>
            <SearchTextInput
              label="Tìm kiếm"
              placeholder="Tìm mã, tên..."
              value={searchDraft}
              onChange={setSearchDraft}
              onSearch={handleSearch}
              testId={`${TEST_ID}-search-text`}
            />
          </>
        )}
        footerPagination={{
          page,
          pageSize: PAGE_SIZE,
          totalCount,
          onPageChange: setPage,
          itemLabel: 'công thức',
        }}
        modals={(
          <LeaveConfirmModal {...leaveConfirmModalProps} />
        )}
      >
        {pageItems.length === 0 && !showTableLoading ? (
          <div className={styles.empty}>
            <i className="fas fa-inbox" />
            <p>{search.trim() ? 'Không tìm thấy công thức' : 'Chưa có công thức — API sẽ seed mặc định khi mở list'}</p>
          </div>
        ) : (
          <table className={styles.table} data-testid={`${TEST_ID}-grid`}>
            <thead className={styles.stickyHead}>
              <tr>
                <th className={styles.thStt}>STT</th>
                <th className={styles.thCode}>Mã</th>
                <th className={styles.thName}>Tên</th>
                <th>Loại</th>
                <th>Engine</th>
                <th className={styles.thSort}>Thứ tự</th>
                <th className={styles.thActive}>TT</th>
                <th className={styles.thActions} />
              </tr>
            </thead>
            <tbody>
              {pageItems.map((record, idx) => (
                <tr
                  key={record.id}
                  className={selectedId === record.id ? styles.rowSelected : undefined}
                  onClick={() => setSelectedId(record.id)}
                  onDoubleClick={() => openView(record)}
                >
                  <td className={styles.cellStt}>{(page - 1) * PAGE_SIZE + idx + 1}</td>
                  <td className={styles.cellCode}><strong>{record.code}</strong></td>
                  <td className={styles.cellName}>
                    {record.name}
                    {record.isDefault ? <Tag color="blue">Mặc định</Tag> : null}
                  </td>
                  <td>{KIND_LABEL[record.formulaKind] || record.formulaKind}</td>
                  <td>{record.engineKey}</td>
                  <td className={styles.cellSort}>{record.sortOrder}</td>
                  <td className={styles.cellActive}>
                    {record.isActive
                      ? <Tag color="green">Kích hoạt</Tag>
                      : <Tag color="default">Tạm ngưng</Tag>}
                  </td>
                  <td className={styles.cellActions} onClick={e => e.stopPropagation()}>
                    <button type="button" className={styles.linkBtn} onClick={() => openView(record)}>Xem</button>
                    {canManageExpansionFormula && (
                      <button type="button" className={styles.linkBtn} onClick={() => openEdit(record)}>Sửa</button>
                    )}
                    {canDeleteExpansionFormula && (
                      <Popconfirm title="Xóa công thức này?" onConfirm={() => void handleDelete(record.id)}>
                        <button type="button" className={styles.linkBtnDanger}>Xóa</button>
                      </Popconfirm>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </LinPageLayout>

      <Modal
        isOpen={modalOpen}
        onClose={closeModal}
        title={modalTitle}
        size="md"
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <Input
            label="Mã *"
            value={form.code}
            disabled={viewOnly || formMode === 'edit'}
            onChange={e => patchForm('code', e.target.value.toUpperCase())}
            error={errors.code}
            data-testid={`${TEST_ID}-code`}
          />
          <Input
            label="Tên *"
            value={form.name}
            disabled={viewOnly}
            onChange={e => patchForm('name', e.target.value)}
            error={errors.name}
            data-testid={`${TEST_ID}-name`}
          />
          <label>
            Loại công thức *
            <Select
              value={form.formulaKind}
              disabled={viewOnly}
              options={KIND_OPTIONS}
              onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                patchForm('formulaKind', (e.target.value as ExpansionFormulaKind) || 'BreakEven')}
              data-testid={`${TEST_ID}-kind`}
            />
          </label>
          <Input
            label="Engine key"
            value={form.engineKey}
            readOnly={viewOnly}
            onChange={e => patchForm('engineKey', e.target.value.toUpperCase())}
            placeholder="VD: BEP_SIMPLE, PB_CUMULATIVE, REC_THRESH"
            data-testid={`${TEST_ID}-engine`}
          />
          {form.formulaKind === 'Recommendation' && (
            <>
              <NumberInput
                label="Ngưỡng nhanh (tháng)"
                value={form.thresholdFast ?? 0}
                readOnly={viewOnly}
                onChange={v => patchForm('thresholdFast', Number.isFinite(v) ? v : null)}
                data-testid={`${TEST_ID}-fast`}
              />
              <NumberInput
                label="Ngưỡng có điều kiện (tháng)"
                value={form.thresholdOk ?? 0}
                readOnly={viewOnly}
                onChange={v => patchForm('thresholdOk', Number.isFinite(v) ? v : null)}
                data-testid={`${TEST_ID}-ok`}
              />
            </>
          )}
          <NumberInput
            label="Thứ tự"
            value={form.sortOrder}
            readOnly={viewOnly}
            onChange={v => patchForm('sortOrder', Number.isFinite(v) ? v : 0)}
          />
          <TextArea
            label="Mô tả"
            value={form.description}
            disabled={viewOnly}
            onChange={e => patchForm('description', e.target.value)}
            rows={3}
          />
          <Checkbox
            label="Kích hoạt"
            checked={form.isActive}
            disabled={viewOnly}
            onChange={e => patchForm('isActive', e.target.checked)}
          />
          <Checkbox
            label="Mặc định cho loại này"
            checked={form.isDefault}
            disabled={viewOnly}
            onChange={e => patchForm('isDefault', e.target.checked)}
          />
          <FormActions align="end">
            <Button onClick={closeModal}>Đóng</Button>
            {!viewOnly && (
              <Button variant="primary" disabled={submitting} onClick={() => void handleSave()}>
                {submitting ? 'Đang lưu…' : 'Lưu'}
              </Button>
            )}
          </FormActions>
        </div>
      </Modal>
    </div>
  );
}
